import{_ as t,o as a,c as s,a0 as o}from"./chunks/framework.Bf27OMyu.js";const p=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Scheduled Sale Manager","text":"Store-wide sales for WooCommerce, on a schedule","tagline":"Run percentage or fixed discounts across the products you choose, on the dates and recurring schedules you set — prices are computed live, never overwritten in your catalog.","actions":[{"theme":"brand","text":"Get Started","link":"/docs/guide/getting-started"},{"theme":"alt","text":"How it works","link":"/docs/guide/how-it-works"},{"theme":"alt","text":"Configure a sale","link":"/docs/sales/overview"}]},"features":[{"title":"Flexible scheduling","details":"Always-on, a fixed date range, or recurring weekly, monthly, and yearly windows. Times follow your store's timezone and stay correct across daylight-saving changes."},{"title":"Target exactly the right products","details":"Match by category, tag, attribute, product age, or specific products. Combine rules with AND inside a group and OR across groups, and exclude what you don't want."},{"title":"Several discount types","details":"A percentage off, a fixed sale price, a fixed amount off, or free shipping — and you can stack multiple effects on a single sale."},{"title":"Prices computed at display time","details":"Sale prices are calculated the moment a price is shown and never written to the product database, so what shoppers see is always accurate to the second."},{"title":"Multiple sales at once","details":"Run overlapping campaigns simultaneously. When more than one sale applies to a product, the lowest resulting price wins automatically."},{"title":"Built to extend","details":"Behavior is overridable through wcssm-* filters and actions, so developers can adjust scheduling, targeting, pricing, and more without touching core files."}]},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}`),i={name:"docs/index.md"};function r(n,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h2 id="what-is-scheduled-sale-manager" tabindex="-1">What is Scheduled Sale Manager? <a class="header-anchor" href="#what-is-scheduled-sale-manager" aria-label="Permalink to &quot;What is Scheduled Sale Manager?&quot;">​</a></h2><p><strong>WooCommerce Scheduled Sale Manager</strong> lets a store owner set up store-wide, scheduled sales from a single place. Instead of editing individual products, you create a <strong>Sale</strong> that says <em>which products</em> are on offer, <em>what the discount is</em>, and <em>when it runs</em> — and the plugin applies it automatically for as long as the schedule is active.</p><p>Each sale brings together four things:</p><ul><li><strong>A schedule</strong> — always on, a one-off date range, or a recurring weekly / monthly / yearly window.</li><li><strong>Targeting criteria</strong> — the products the sale applies to, by category, tag, attribute, age, or specific selection.</li><li><strong>Discounts</strong> — a percentage, a fixed price, a fixed reduction, or free shipping.</li><li><strong>Per-sale settings</strong> — finer control such as whether to apply on top of an existing discount price.</li></ul><h2 id="why-prices-aren-t-stored" tabindex="-1">Why prices aren&#39;t stored <a class="header-anchor" href="#why-prices-aren-t-stored" aria-label="Permalink to &quot;Why prices aren&#39;t stored&quot;">​</a></h2><p>The plugin <strong>never writes sale prices into your product database</strong>. It computes the effective price the instant a price is read, by hooking WooCommerce&#39;s own price filters. That means the displayed price always reflects the exact moment it&#39;s shown, several sales can be active at once, and turning a sale off restores original prices immediately — with nothing to clean up. (One consequence: tools that read prices straight from the database, bypassing WooCommerce, will see the regular price. See <a href="/wcssm2/docs/guide/how-it-works">How it works</a>.)</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>New here? Start with the <a href="/wcssm2/docs/guide/introduction">Introduction</a> and <a href="/wcssm2/docs/guide/getting-started">Getting Started</a>.</li><li>Ready to build one? Walk through <a href="/wcssm2/docs/sales/overview">configuring a sale</a>.</li><li>Curious about the engine? Read <a href="/wcssm2/docs/guide/how-it-works">How it works</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Requirements</p><p>WooCommerce must be installed and active — the plugin does nothing without it.</p></div>',9)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
